css:
body[data-theme="technical"] { background: #0B0F19; color: #E5E7EB; font-family: 'IBM Plex Sans', ui-sans-serif, system-ui, sans-serif; }
body[data-theme="technical"] .display { font-family: 'IBM Plex Sans', ui-sans-serif, sans-serif; font-weight: 600; letter-spacing: -0.01em; }
body[data-theme="technical"] .num-marker { font-family: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace; font-variant-numeric: tabular-nums; font-feature-settings: 'tnum'; }
/* surfaces */
body[data-theme="technical"].bg-white,
body[data-theme="technical"] .bg-white,
body[data-theme="technical"] header.sticky { background: #0B0F19 !important; }
body[data-theme="technical"] header.sticky { background: rgba(11,15,25,0.85) !important; border-color: #1F2937 !important; }
body[data-theme="technical"] .bg-slate-50 { background: #111827 !important; }
/* text scale */
body[data-theme="technical"] .text-slate-900 { color: #F1F5F9 !important; }
body[data-theme="technical"] .text-slate-700 { color: #CBD5E1 !important; }
body[data-theme="technical"] .text-slate-600 { color: #94A3B8 !important; }
body[data-theme="technical"] .text-slate-500 { color: #64748B !important; }
body[data-theme="technical"] .text-slate-400 { color: #475569 !important; }
body[data-theme="technical"] .text-slate-300 { color: #334155 !important; }
/* borders + rules */
body[data-theme="technical"] .border-slate-200 { border-color: #1F2937 !important; }
body[data-theme="technical"] .rule { background: linear-gradient(to right, transparent, #1F2937, transparent) !important; }
/* eyebrows feel terminal-like */
body[data-theme="technical"] .uppercase.tracking-\[0\.2em\] { font-family: 'JetBrains Mono', ui-monospace, monospace; letter-spacing: 0.12em; }
